"""Canonical score model (FND-001).

A ScoreDocument is *concert pitch only*. Horn in F is a derived presentation
of the same canonical notes and therefore shares canonical note IDs.

Timing model: score positions are rational beat positions (Fraction), never
float seconds. Source seconds are reachable only through the tempo map /
provenance layer.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from enum import Enum
from fractions import Fraction
from itertools import pairwise
from typing import Any

from hornscribe.domain.ids import (
    ProjectId,
    RawNoteEventId,
    ScoreNoteId,
    ScoreRevisionId,
    derive_score_revision_id,
)


class PitchSpace(Enum):
    """The only pitch space allowed for canonical storage is CONCERT."""

    CONCERT = "concert"
    WRITTEN_HORN_F = "written_horn_f"  # presentation/export only, never canonical


@dataclass(frozen=True)
class ScoreAtom:
    """One written symbol inside a canonical note or rest (QNT-006).

    ``duration_beats`` is the atom's exact span on the canonical beat axis;
    ``symbol`` + ``dots`` + ``tuplet`` describe how it is written. These are
    the quantizer's committed notation decisions — HSQ decides the written
    decomposition, the notation layer only renders it (architecture rule:
    music21 realizes/serializes, never re-quantizes).

    ``tie_to_next`` joins this atom to the following atom *inside the same
    canonical note's* atom list; it is always ``False`` on a note's last atom
    and always ``False`` on rest atoms (rests never tie).
    """

    duration_beats: Fraction
    """Exact span of the written symbol (e.g. a triplet eighth = 1/3 beat in
    a quarter-note-beat meter)."""
    symbol: str
    """Base symbol name: ``"whole"``, ``"half"``, ``"quarter"``, ``"eighth"``,
    ``"sixteenth"``, ``"32nd"``, ``"64th"``."""
    dots: int = 0
    tuplet: str | None = None
    """Tuplet label (``"triplet"`` in HSQ-v1), or ``None`` for binary atoms."""
    tuplet_group_start: bool = False
    """``True`` when this atom opens a new visual tuplet group (MusicXML
    ``<tuplet type="start">``); the last tuplet atom before the next
    ``tuplet_group_start``/non-tuplet atom closes it."""
    tie_to_next: bool = False

    def __post_init__(self) -> None:
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        if self.duration_beats <= 0:
            raise ValueError(f"atom duration_beats must be > 0, got {self.duration_beats}")
        if not self.symbol:
            raise ValueError("atom symbol must be a non-empty string")
        if (
            isinstance(self.dots, bool)
            or not isinstance(self.dots, int)
            or not 0 <= self.dots <= 2
        ):
            raise ValueError(f"atom dots must be in 0..2, got {self.dots!r}")
        if self.tuplet is not None and not self.tuplet:
            raise ValueError("atom tuplet must be None or a non-empty label")
        if self.tuplet_group_start and self.tuplet is None:
            raise ValueError("tuplet_group_start requires a tuplet atom")

    def to_dict(self) -> dict[str, Any]:
        return {
            "durationBeats": _frac(self.duration_beats),
            "symbol": self.symbol,
            "dots": self.dots,
            "tuplet": self.tuplet,
            "tupletGroupStart": self.tuplet_group_start,
            "tieToNext": self.tie_to_next,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreAtom:
        return cls(
            duration_beats=_unfrac(data["durationBeats"]),
            symbol=str(data["symbol"]),
            dots=int(data.get("dots", 0)),
            tuplet=data.get("tuplet"),
            tuplet_group_start=bool(data.get("tupletGroupStart", False)),
            tie_to_next=bool(data.get("tieToNext", False)),
        )


@dataclass(frozen=True)
class ScoreRest:
    """A realized rest span: start position plus its written rest atoms.

    Rests carry no canonical identity (``ids.py``: rest ``note/@id`` values
    are presentation-only). The atoms tile ``[start_beat, start_beat +
    total)`` exactly, never tie, and never cross a barline — a multi-measure
    rest span contains one atom group per measure (a complete empty measure
    is a single ``"whole"`` atom = the measure-rest convention).
    """

    start_beat: Fraction
    atoms: tuple[ScoreAtom, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        if self.start_beat < 0:
            raise ValueError(f"rest start_beat must be >= 0, got {self.start_beat}")
        if not self.atoms:
            raise ValueError("a rest span needs at least one atom")
        for atom in self.atoms:
            if not isinstance(atom, ScoreAtom):
                raise TypeError(f"expected ScoreAtom, got {atom!r}")
            if atom.tie_to_next:
                raise ValueError("rest atoms cannot tie to the next atom")

    @property
    def duration_beats(self) -> Fraction:
        """Total exact span covered by the rest atoms."""
        return sum((a.duration_beats for a in self.atoms), Fraction(0))

    @property
    def end_beat(self) -> Fraction:
        """End of the rest span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "atoms": [a.to_dict() for a in self.atoms],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRest:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
        )


@dataclass(frozen=True)
class QuantizedNote:
    """A canonical score note in rational beat positions.

    ``atoms`` is the optional written decomposition committed by the
    quantizer (QNT-006): when present it tiles ``duration_beats`` exactly,
    every atom but the last carries ``tie_to_next``, and no atom crosses a
    barline (barline/beat splits are already materialized as separate tied
    atoms). When empty the notation layer falls back to deriving the written
    decomposition itself (legacy/provisional scores).
    """

    id: ScoreNoteId
    source_event_ids: tuple[RawNoteEventId, ...]
    pitch_midi: int
    start_beat: Fraction
    duration_beats: Fraction
    velocity: int | None = None
    tie_start: bool = False
    tie_stop: bool = False
    atoms: tuple[ScoreAtom, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        if self.start_beat < 0:
            raise ValueError(f"start_beat must be >= 0, got {self.start_beat}")
        if self.duration_beats <= 0:
            raise ValueError(f"duration_beats must be > 0, got {self.duration_beats}")
        if self.atoms:
            for atom in self.atoms:
                if not isinstance(atom, ScoreAtom):
                    raise TypeError(f"expected ScoreAtom, got {atom!r}")
            total = sum((a.duration_beats for a in self.atoms), Fraction(0))
            if total != self.duration_beats:
                raise ValueError(
                    f"note atoms total {total} != duration_beats {self.duration_beats}"
                )
            if self.atoms[-1].tie_to_next:
                raise ValueError("a note's last atom cannot tie_to_next")
            for atom in self.atoms[:-1]:
                if not atom.tie_to_next:
                    raise ValueError(
                        "interior atoms of a note must tie to the next atom "
                        "(an untied boundary would read as two notes)"
                    )

    @property
    def end_beat(self) -> Fraction:
        """End of the note span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": str(self.id),
            "sourceEventIds": [str(e) for e in self.source_event_ids],
            "pitchMidi": self.pitch_midi,
            "startBeat": _frac(self.start_beat),
            "durationBeats": _frac(self.duration_beats),
            "velocity": self.velocity,
            "tieStart": self.tie_start,
            "tieStop": self.tie_stop,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs (content-derived identity, ids.py).
        if self.atoms:
            data["atoms"] = [a.to_dict() for a in self.atoms]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> QuantizedNote:
        return cls(
            id=ScoreNoteId(data["id"]),
            source_event_ids=tuple(RawNoteEventId(e) for e in data.get("sourceEventIds", ())),
            pitch_midi=int(data["pitchMidi"]),
            start_beat=_unfrac(data["startBeat"]),
            duration_beats=_unfrac(data["durationBeats"]),
            velocity=data.get("velocity"),
            tie_start=bool(data.get("tieStart", False)),
            tie_stop=bool(data.get("tieStop", False)),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
        )


@dataclass(frozen=True)
class TempoSegment:
    start_beat: Fraction
    bpm: float

    def to_dict(self) -> dict[str, Any]:
        return {"startBeat": _frac(self.start_beat), "bpm": self.bpm}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TempoSegment:
        return cls(start_beat=_unfrac(data["startBeat"]), bpm=float(data["bpm"]))


@dataclass(frozen=True)
class TimeSignature:
    beats_per_measure: int
    beat_unit: int

    def to_dict(self) -> dict[str, Any]:
        return {"beatsPerMeasure": self.beats_per_measure, "beatUnit": self.beat_unit}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TimeSignature:
        return cls(
            beats_per_measure=int(data["beatsPerMeasure"]),
            beat_unit=int(data["beatUnit"]),
        )


@dataclass(frozen=True)
class KeySignature:
    """Fifths (-7..7) plus mode."""

    fifths: int
    mode: str = "major"

    def to_dict(self) -> dict[str, Any]:
        return {"fifths": self.fifths, "mode": self.mode}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeySignature:
        return cls(fifths=int(data["fifths"]), mode=str(data.get("mode", "major")))


@dataclass(frozen=True)
class KeyChange:
    """A key-signature boundary on the canonical beat axis (#133).

    The key_signature is active from start_beat until the next
    change's start_beat (or indefinitely for the last change) —
    the key-map analogue of MeterChange, without a phase concept
    (keys do not affect measure layout).
    """

    start_beat: Fraction
    key_signature: KeySignature

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        if self.start_beat < 0:
            raise ValueError(
                f"key change start_beat must be >= 0, got {self.start_beat}"
            )

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "keySignature": self.key_signature.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeyChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
        )


@dataclass(frozen=True)
class MeterChange:
    """A meter segment boundary on the canonical beat axis (QNT-006).

    The meter ``time_signature`` is active from ``start_beat`` until the
    next change's ``start_beat`` (or indefinitely for the last change).
    ``measure_phase_beats`` is the metrical offset of ``start_beat`` inside
    its measure cycle — the mid-piece analogue of ``pickup_beats``: ``0``
    means the change lands on a downbeat; ``p > 0`` means the segment's
    first measure covers only its last ``measure_length - p`` beats.
    """

    start_beat: Fraction
    time_signature: TimeSignature
    measure_phase_beats: Fraction = Fraction(0)

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(
            self, "measure_phase_beats", _unfrac(self.measure_phase_beats)
        )
        if self.start_beat < 0:
            raise ValueError(f"meter change start_beat must be >= 0, got {self.start_beat}")
        if self.measure_phase_beats < 0:
            raise ValueError(
                f"measure_phase_beats must be >= 0, got {self.measure_phase_beats}"
            )
        # The upper bound (phase < measure length) needs the canonical beat
        # unit, which only the owning ScoreRevisionPayload knows — it is
        # validated there.

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "timeSignature": self.time_signature.to_dict(),
            "measurePhaseBeats": _frac(self.measure_phase_beats),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> MeterChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            measure_phase_beats=_unfrac(data.get("measurePhaseBeats", "0/1")),
        )


@dataclass(frozen=True)
class Part:
    """A single staff part containing canonical notes in score order.

    ``rests`` is the committed rest list (QNT-006): when non-empty the
    notation layer renders exactly these rest atoms and requires notes+rests
    to tile every measure — no gap-filling. When empty (legacy/provisional
    scores) the notation layer fills inter-note gaps itself.
    """

    id: str
    name: str
    notes: tuple[QuantizedNote, ...] = field(default_factory=tuple)
    rests: tuple[ScoreRest, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        object.__setattr__(self, "notes", tuple(self.notes))
        object.__setattr__(self, "rests", tuple(self.rests))
        ordered = sorted(self.rests, key=lambda r: r.start_beat)
        if tuple(ordered) != self.rests:
            raise ValueError("part rests must be in start_beat order")
        for prev, cur in pairwise(self.rests):
            if cur.start_beat < prev.end_beat:
                raise ValueError(
                    f"overlapping rests: {prev.start_beat}+{prev.duration_beats} "
                    f"vs {cur.start_beat}"
                )

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": self.id,
            "name": self.name,
            "notes": [n.to_dict() for n in self.notes],
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.rests:
            data["rests"] = [r.to_dict() for r in self.rests]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Part:
        return cls(
            id=str(data["id"]),
            name=str(data["name"]),
            notes=tuple(QuantizedNote.from_dict(n) for n in data.get("notes", ())),
            rests=tuple(ScoreRest.from_dict(r) for r in data.get("rests", ())),
        )


def _frac(value: Fraction) -> str:
    return f"{value.numerator}/{value.denominator}"


def _unfrac(value: Any) -> Fraction:
    if isinstance(value, Fraction):
        return value
    if isinstance(value, str):
        return Fraction(value)
    return Fraction(value)


@dataclass(frozen=True)
class ScoreRevisionPayload:
    """The canonical content a score revision ID is derived from.

    Anything that changes the *musical content* of the score belongs here so
    that revision IDs track content, not serialization accidents.

    ``meter_changes`` is the full ordered meter map when the piece changes
    meter (QNT-006); when present it is authoritative for measure layout,
    its first entry must sit at beat ``0`` with ``time_signature`` matching
    the payload's own ``time_signature`` field, and its first
    ``measure_phase_beats`` must agree with ``pickup_beats``. When empty,
    layout derives from ``time_signature`` + ``pickup_beats`` alone (the
    single-meter legacy path).
    """

    tempo_map: tuple[TempoSegment, ...]
    time_signature: TimeSignature
    key_signature: KeySignature
    pickup_beats: Fraction
    parts: tuple[Part, ...]
    quantization_settings: dict[str, Any]
    meter_changes: tuple[MeterChange, ...] = ()
    """#133: key-signature boundaries — mirrors meter_changes (first
    entry at beat 0 carrying the payload key_signature, strictly
    increasing starts). Empty = single-key legacy path."""
    key_changes: tuple[KeyChange, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "tempo_map", tuple(self.tempo_map))
        object.__setattr__(self, "parts", tuple(self.parts))
        object.__setattr__(self, "meter_changes", tuple(self.meter_changes))
        object.__setattr__(self, "key_changes", tuple(self.key_changes))
        object.__setattr__(self, "pickup_beats", _unfrac(self.pickup_beats))
        if self.pickup_beats < 0:
            raise ValueError(f"pickup_beats must be >= 0, got {self.pickup_beats}")
        ts0 = self.time_signature
        if ts0.beats_per_measure <= 0 or ts0.beat_unit <= 0:
            raise ValueError(
                f"invalid time signature: {ts0.beats_per_measure}/{ts0.beat_unit}"
            )
        if self.key_changes:
            if self.key_changes[0].start_beat != 0:
                raise ValueError(
                    "first key change must start at beat 0, got "
                    f"{self.key_changes[0].start_beat}"
                )
            if self.key_changes[0].key_signature != self.key_signature:
                raise ValueError(
                    "first key change must carry the payload key_signature: "
                    f"{self.key_changes[0].key_signature} != {self.key_signature}"
                )
            for prev_key, cur_key in pairwise(self.key_changes):
                if cur_key.start_beat <= prev_key.start_beat:
                    raise ValueError(
                        "key changes must be strictly increasing: "
                        f"{prev_key.start_beat} !< {cur_key.start_beat}"
                    )
        if not self.meter_changes:
            # Legacy single-meter path: pickup must fit inside a measure of
            # the (beat-defining) first time signature.
            if self.pickup_beats >= ts0.beats_per_measure:
                raise ValueError(
                    f"pickup_beats {self.pickup_beats} must be shorter than a "
                    f"{ts0.beats_per_measure}-beat measure"
                )
            return
        first = self.meter_changes[0]
        if first.start_beat != 0:
            raise ValueError(
                f"first meter change must start at beat 0, got {first.start_beat}"
            )
        if first.time_signature != ts0:
            raise ValueError(
                "first meter change must carry the payload time_signature: "
                f"{first.time_signature} != {ts0}"
            )
        beat_ql = Fraction(4, ts0.beat_unit)
        expected_phase = (
            Fraction(ts0.beats_per_measure) - self.pickup_beats
            if self.pickup_beats > 0
            else Fraction(0)
        )
        if first.measure_phase_beats != expected_phase:
            raise ValueError(
                f"first meter change phase {first.measure_phase_beats} "
                f"disagrees with pickup_beats {self.pickup_beats} "
                f"(expected {expected_phase})"
            )
        for prev, cur in pairwise(self.meter_changes):
            if cur.start_beat <= prev.start_beat:
                raise ValueError(
                    "meter changes must be strictly increasing: "
                    f"{prev.start_beat} !< {cur.start_beat}"
                )
        for change in self.meter_changes:
            mlen = measure_length_beats(change.time_signature, beat_ql)
            if change.measure_phase_beats >= mlen:
                raise ValueError(
                    f"meter change at {change.start_beat} has phase "
                    f"{change.measure_phase_beats} >= measure length {mlen}"
                )
    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "tempoMap": [t.to_dict() for t in self.tempo_map],
            "timeSignature": self.time_signature.to_dict(),
            "keySignature": self.key_signature.to_dict(),
            "pickupBeats": _frac(self.pickup_beats),
            "parts": [p.to_dict() for p in self.parts],
            "quantizationSettings": self.quantization_settings,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.meter_changes:
            data["meterChanges"] = [m.to_dict() for m in self.meter_changes]
        if self.key_changes:
            data["keyChanges"] = [k.to_dict() for k in self.key_changes]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRevisionPayload:
        return cls(
            tempo_map=tuple(TempoSegment.from_dict(t) for t in data.get("tempoMap", ())),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
            pickup_beats=_unfrac(data.get("pickupBeats", "0/1")),
            parts=tuple(Part.from_dict(p) for p in data.get("parts", ())),
            quantization_settings=dict(data.get("quantizationSettings", {})),
            meter_changes=tuple(
                MeterChange.from_dict(m) for m in data.get("meterChanges", ())
            ),
            key_changes=tuple(
                KeyChange.from_dict(k) for k in data.get("keyChanges", ())
            ),
        )

    def revision_id(self) -> ScoreRevisionId:
        return derive_score_revision_id(self.to_dict())


def beat_ql_of(payload: ScoreRevisionPayload) -> Fraction:
    """QuarterLength of one canonical beat — set by the first time signature.

    With a single meter this is simply ``4/beat_unit``. With meter changes
    the *first* meter change defines the beat axis for the whole score, so
    positions stay comparable across segment boundaries.
    """
    return Fraction(4, payload.time_signature.beat_unit)


def measure_length_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """One measure of *ts* expressed in canonical beats.

    ``ts.beats_per_measure * (4/beat_unit)`` gives the measure length in
    quarterLength; dividing by ``beat_ql`` converts to canonical beats
    (for the beat-defining signature this is just ``beats_per_measure``).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    return Fraction(ts.beats_per_measure * 4, ts.beat_unit) / beat_ql


def primary_beat_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """Length of one primary (felt) beat of *ts* in canonical beats.

    Compound meters (``numerator % 3 == 0 and numerator > 3`` — e.g. 6/8)
    have ``numerator // 3`` dotted beats; simple meters beat on the
    denominator unit. Mirrors ``MeterSegment.beat_unit_ql`` (design 7.3).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    beat_count = (
        ts.beats_per_measure // 3
        if ts.beats_per_measure % 3 == 0 and ts.beats_per_measure > 3
        else ts.beats_per_measure
    )
    return measure_length_beats(ts, beat_ql) / beat_count


@dataclass(frozen=True)
class MeasureSpan:
    """One measure's span on the canonical beat axis.

    ``number`` is the MusicXML measure number (``0`` for the implicit
    anacrusis measure); ``time_signature`` is the meter active inside the
    measure; ``meter_change`` marks the first measure of a new meter — the
    notation layer emits ``<time>`` attributes there;
    ``cycle_offset_beats`` is the span's position inside its meter's measure
    cycle (``0`` except for the partial first measure of a phased segment).
    """

    number: int
    start_beat: Fraction
    end_beat: Fraction
    time_signature: TimeSignature
    meter_change: bool = False
    implicit: bool = False
    cycle_offset_beats: Fraction = Fraction(0)

    @property
    def duration_beats(self) -> Fraction:
        return self.end_beat - self.start_beat


def measure_spans(payload: ScoreRevisionPayload) -> tuple[MeasureSpan, ...]:
    """Deterministic measure layout shared by every part and every consumer.

    Layout rules (QNT-006):

    * each meter change tiles measures from its ``start_beat`` until the next
      change (or the content end for the last change), each first measure
      shortened by its ``measure_phase_beats``;
    * a meter change that falls inside a previous measure *clips* it — the
      partial measure keeps its number;
    * a ``measure_phase_beats > 0`` on the *first* change is the anacrusis:
      measure ``0`` with ``implicit`` (the existing convention); phased
      mid-piece changes keep regular numbering;
    * every segment emits at least one measure, so a meter declared beyond
      the content end still appears (as an empty measure);
    * with no ``meter_changes`` this degenerates to the historical layout:
      optional implicit pickup measure plus ``beats_per_measure`` tiling.
    """
    changes = payload.meter_changes
    if not changes:
        ts0 = payload.time_signature
        mlen0 = Fraction(ts0.beats_per_measure)
        phase0 = (
            mlen0 - payload.pickup_beats if payload.pickup_beats > 0 else Fraction(0)
        )
        changes = (MeterChange(Fraction(0), ts0, phase0),)
    beat_ql = beat_ql_of(payload)

    end = payload.pickup_beats
    for part in payload.parts:
        for n in part.notes:
            end = max(end, n.end_beat)
        for r in part.rests:
            end = max(end, r.end_beat)

    spans: list[MeasureSpan] = []
    number = 1
    for i, change in enumerate(changes):
        seg_end = changes[i + 1].start_beat if i + 1 < len(changes) else None
        mlen = measure_length_beats(change.time_signature, beat_ql)
        pos = change.start_beat
        first = True
        while first or (pos < seg_end if seg_end is not None else pos < end):
            dur = mlen - change.measure_phase_beats if first else mlen
            m_end = pos + dur
            if seg_end is not None and m_end > seg_end:
                m_end = seg_end
            if m_end <= pos:
                break  # safety: zero-length measure
            implicit = first and i == 0 and change.measure_phase_beats > 0
            span_number = 0 if implicit else number
            if not implicit:
                number += 1
            spans.append(
                MeasureSpan(
                    number=span_number,
                    start_beat=pos,
                    end_beat=m_end,
                    time_signature=change.time_signature,
                    meter_change=first and i > 0,
                    implicit=implicit,
                    cycle_offset_beats=(
                        change.measure_phase_beats if first else Fraction(0)
                    ),
                )
            )
            pos = m_end
            first = False
    return tuple(spans)


@dataclass(frozen=True)
class ScoreDocument:
    """Canonical score container. ``payload`` carries all musical content."""

    project_id: ProjectId
    payload: ScoreRevisionPayload
    title: str = ""
    source_audio_path: str | None = None
    source_audio_hash: str | None = None
    transcription_backend: str | None = None
    transcription_backend_version: str | None = None
    transcription_settings: dict[str, Any] = field(default_factory=dict)
    pitch_space: PitchSpace = PitchSpace.CONCERT

    @property
    def revision(self) -> ScoreRevisionId:
        return self.payload.revision_id()

    def to_dict(self) -> dict[str, Any]:
        if self.pitch_space is not PitchSpace.CONCERT:
            raise ValueError("canonical ScoreDocument must be concert pitch")
        return {
            "projectId": str(self.project_id),
            "revision": str(self.revision),
            "title": self.title,
            "sourceAudioPath": self.source_audio_path,
            "sourceAudioHash": self.source_audio_hash,
            "transcriptionBackend": self.transcription_backend,
            "transcriptionBackendVersion": self.transcription_backend_version,
            "transcriptionSettings": self.transcription_settings,
            "pitchSpace": self.pitch_space.value,
            "content": self.payload.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreDocument:
        space = PitchSpace(data.get("pitchSpace", "concert"))
        doc = cls(
            project_id=ProjectId(data["projectId"]),
            payload=ScoreRevisionPayload.from_dict(data["content"]),
            title=str(data.get("title", "")),
            source_audio_path=data.get("sourceAudioPath"),
            source_audio_hash=data.get("sourceAudioHash"),
            transcription_backend=data.get("transcriptionBackend"),
            transcription_backend_version=data.get("transcriptionBackendVersion"),
            transcription_settings=dict(data.get("transcriptionSettings", {})),
            pitch_space=space,
        )
        declared = data.get("revision")
        if declared is not None and declared != str(doc.revision):
            raise ValueError(
                f"score revision mismatch: declared {declared} != derived {doc.revision}"
            )
        return doc


def new_project_id() -> ProjectId:
    """Random project ID for genuinely new projects (creation-time only)."""
    from hornscribe.domain.ids import derive_project_id

    return derive_project_id({"uuid": uuid.uuid4().hex})

"""Render a canonical :class:`ScoreDocument` into a music21 stream.

HornScribe domain objects stay authoritative; this module only *renders*
them into ``music21`` objects so that music21 can carry the engraving-level
MusicXML details (dev plan §13).  Every pitched ``music21`` note is tagged
with its deterministic MusicXML export ID (:func:`musicxml_note_id`) before
serialization, so emitted ``note/@id`` values always trace back to canonical
identity.

QNT-006 architecture rule: HSQ decides musical onset/duration/rest/tie/
tuplet intent; music21 only realizes and serializes it.  When canonical
notes carry ``atoms`` (the quantizer's committed written decomposition) and
the part carries explicit ``rests``, this module places *those* atoms —
typed ``Duration`` objects built from the committed symbol/dots/tuplet —
rather than letting music21 infer note values from raw quarterLengths, and
it never invokes music21's quantizer.  Scores without atoms/rests (legacy
or provisional payloads) fall back to the previous path: barline-split
note fragments plus measure gap rests.

Responsibilities:

* measure construction from the canonical meter map (``meter_changes`` or
  the single ``time_signature`` + ``pickup_beats``), including mid-piece
  ``<time>`` attribute changes
* rendering canonical note atoms and rest atoms, honoring committed ties,
  tuplets (``<time-modification>`` + ``<tuplet>`` brackets), and the
  whole-rest-as-measure-rest convention
* splitting notes that cross barlines into tied fragments (legacy path)
* inserting rests for gaps inside measures (legacy path)
* written-pitch projection for the Horn in F presentation
  (``PitchSpace.WRITTEN_HORN_F``), including the transposed key signature
  and the ``instrument.Horn`` that produces ``<transpose>-4/-7`` metadata
* tempo map -> ``MetronomeMark`` placement

Non-responsibilities: enharmonic respelling beyond music21's defaults
(dev plan §11 keeps that as a later, user-adjustable stage).
"""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import Literal

from music21 import (
    clef,
    duration,
    instrument,
    key,
    metadata,
    meter,
    note,
    pitch,
    stream,
    tempo,
    tie,
)
from music21.stream import enums as stream_enums

from hornscribe.domain.ids import musicxml_note_id
from hornscribe.domain.score import (
    MeasureSpan,
    PitchSpace,
    QuantizedNote,
    ScoreAtom,
    ScoreDocument,
    ScoreRest,
    ScoreRevisionPayload,
    beat_ql_of,
    measure_length_beats,
    measure_spans,
)
from hornscribe.instruments import horn_f


class NotationError(ValueError):
    """Canonical content that cannot be rendered into MVP notation."""


#: Canonical atom symbol -> music21 duration type.  music21 spells
#: sixteenth-and-shorter types ordinally (``"16th"``, ``"32nd"``).
_SYMBOL_TO_M21_TYPE: dict[str, str] = {
    "whole": "whole",
    "half": "half",
    "quarter": "quarter",
    "eighth": "eighth",
    "sixteenth": "16th",
    "32nd": "32nd",
    "64th": "64th",
}

#: Canonical tuplet label -> (actual, normal) note counts for
#: ``<time-modification>``.  HSQ-v1 knows only eighth/quarter triplets.
_TUPLET_RATIOS: dict[str, tuple[int, int]] = {"triplet": (3, 2)}


def _content_end_beat(payload: ScoreRevisionPayload) -> Fraction:
    end = payload.pickup_beats
    for part in payload.parts:
        for n in part.notes:
            end = max(end, n.start_beat + n.duration_beats)
        for r in part.rests:
            end = max(end, r.end_beat)
    return end


def _tie_for(piece_index: int, piece_count: int, note_: QuantizedNote) -> tie.Tie | None:
    """Tie for one emitted fragment of a canonical note (legacy path).

    ``tie_stop`` on the canonical note = incoming tie on the *first*
    fragment; ``tie_start`` = outgoing tie on the *last* fragment.
    Fragments produced by barline splits tie to each other; interior
    fragments use ``continue`` (exported as stop+start).
    """
    tie_in = piece_index > 0 or note_.tie_stop
    tie_out = piece_index < piece_count - 1 or note_.tie_start
    if tie_in and tie_out:
        return tie.Tie("continue")
    if tie_in:
        return tie.Tie("stop")
    if tie_out:
        return tie.Tie("start")
    return None


def _atom_tie(
    atom: ScoreAtom, is_first: bool, is_last: bool, note_: QuantizedNote
) -> tie.Tie | None:
    """Tie for one committed atom of a canonical note.

    Interior atom boundaries come from ``tie_to_next``; the canonical
    ``tie_stop``/``tie_start`` flags attach to the first/last atom.
    """
    tie_in = not is_first or note_.tie_stop
    tie_out = atom.tie_to_next or (is_last and note_.tie_start)
    if tie_in and tie_out:
        return tie.Tie("continue")
    if tie_in:
        return tie.Tie("stop")
    if tie_out:
        return tie.Tie("start")
    return None


def _typed_duration(atom: ScoreAtom, beat_ql: Fraction) -> duration.Duration:
    """Build a music21 ``Duration`` from a committed atom.

    The atom's ``symbol``/``dots``/``tuplet`` fully determine the quarter
    length — constructing the Duration from them (instead of assigning a
    quarterLength, which makes music21 re-derive the type) is what keeps
    the notation layer from re-quantizing HSQ's decisions.  The derived
    quarterLength is verified against the atom's exact span; a mismatch
    means the atom is not writable as a single symbol.
    """
    type_str = _SYMBOL_TO_M21_TYPE.get(atom.symbol)
    if type_str is None:
        raise NotationError(f"unwritable atom symbol: {atom.symbol!r}")
    d = duration.Duration(type=type_str, dots=atom.dots)
    if atom.tuplet is not None:
        ratio = _TUPLET_RATIOS.get(atom.tuplet)
        if ratio is None:
            raise NotationError(f"unsupported tuplet label: {atom.tuplet!r}")
        d.appendTuplet(duration.Tuplet(*ratio))
    expected_ql = atom.duration_beats * beat_ql
    if d.quarterLength != expected_ql:
        raise NotationError(
            f"atom {atom.symbol}+{atom.dots}dot tuplet={atom.tuplet} realizes "
            f"{d.quarterLength} ql but commits {expected_ql} ql"
        )
    return d


@dataclass(frozen=True)
class _Entry:
    """One committed element placed inside a measure."""

    kind: str  # "note" | "rest" | "legacy-note" (note without atoms)
    local_start_beats: Fraction
    dur_beats: Fraction
    note_: QuantizedNote | None = None
    atom: ScoreAtom | None = None
    atom_index: int = 0
    piece_index: int = 0
    piece_count: int = 1

    @property
    def local_end_beats(self) -> Fraction:
        return self.local_start_beats + self.dur_beats


def _note_pieces(
    note_: QuantizedNote, spans: tuple[MeasureSpan, ...]
) -> list[tuple[int, Fraction, Fraction]]:
    """Split a canonical note into ``(span_index, local_offset_beats, dur_beats)``."""
    start = note_.start_beat
    end = start + note_.duration_beats
    if start < 0 or note_.duration_beats <= 0:
        raise NotationError(
            f"note {note_.id} has invalid start/duration: {start}+{note_.duration_beats}"
        )
    pieces: list[tuple[int, Fraction, Fraction]] = []
    for idx, span in enumerate(spans):
        if span.end_beat <= start:
            continue
        if span.start_beat >= end:
            break
        piece_start = max(start, span.start_beat)
        piece_end = min(end, span.end_beat)
        if piece_end > piece_start:
            pieces.append((idx, piece_start - span.start_beat, piece_end - piece_start))
    if not pieces:
        raise NotationError(f"note {note_.id} does not overlap any measure")
    return pieces


def _atom_measure_index(
    atom_start: Fraction, atom_end: Fraction, spans: tuple[MeasureSpan, ...], owner: str
) -> int:
    """Index of the measure containing a committed atom (barline check).

    Canonical atoms never cross a barline — if one does, the atom list is
    inconsistent and rendering must fail loudly rather than let music21
    silently re-split it.
    """
    for idx, span in enumerate(spans):
        if span.start_beat <= atom_start < span.end_beat:
            if atom_end > span.end_beat:
                raise NotationError(
                    f"{owner} atom [{atom_start}, {atom_end}) crosses the "
                    f"barline at {span.end_beat}"
                )
            return idx
    raise NotationError(f"{owner} atom at {atom_start} falls outside all measures")


def _measure_entries(
    part_notes: list[QuantizedNote],
    part_rests: tuple[ScoreRest, ...],
    spans: tuple[MeasureSpan, ...],
) -> dict[int, list[_Entry]]:
    """Distribute committed atoms / legacy note pieces into measures."""
    entries: dict[int, list[_Entry]] = {}
    for n in part_notes:
        if n.atoms:
            pos = n.start_beat
            for i, atom in enumerate(n.atoms):
                sidx = _atom_measure_index(
                    pos, pos + atom.duration_beats, spans, f"note {n.id}"
                )
                entries.setdefault(sidx, []).append(
                    _Entry(
                        kind="note",
                        local_start_beats=pos - spans[sidx].start_beat,
                        dur_beats=atom.duration_beats,
                        note_=n,
                        atom=atom,
                        atom_index=i,
                    )
                )
                pos += atom.duration_beats
        else:
            pieces = _note_pieces(n, spans)
            for pidx, (sidx, local_start, dur) in enumerate(pieces):
                entries.setdefault(sidx, []).append(
                    _Entry(
                        kind="legacy-note",
                        local_start_beats=local_start,
                        dur_beats=dur,
                        note_=n,
                        piece_index=pidx,
                        piece_count=len(pieces),
                    )
                )
    for r in part_rests:
        pos = r.start_beat
        for atom in r.atoms:
            sidx = _atom_measure_index(
                pos, pos + atom.duration_beats, spans, f"rest at {r.start_beat}"
            )
            entries.setdefault(sidx, []).append(
                _Entry(
                    kind="rest",
                    local_start_beats=pos - spans[sidx].start_beat,
                    dur_beats=atom.duration_beats,
                    atom=atom,
                )
            )
            pos += atom.duration_beats
    return entries


def _check_monophonic(notes: tuple[QuantizedNote, ...]) -> None:
    """MVP renders one voice per part; overlapping onsets are rejected."""
    ordered = sorted(notes, key=lambda n: (n.start_beat, n.id))
    prev_end: Fraction | None = None
    prev_id: str | None = None
    for n in ordered:
        if prev_end is not None and n.start_beat < prev_end:
            raise NotationError(
                f"overlapping notes in one part are unsupported: {prev_id} ends at "
                f"{prev_end} but {n.id} starts at {n.start_beat}"
            )
        prev_end = n.start_beat + n.duration_beats
        prev_id = str(n.id)


def _pitch_midi(note_: QuantizedNote, presentation: PitchSpace) -> int:
    return (
        horn_f.concert_to_written_midi(note_.pitch_midi)
        if presentation is PitchSpace.WRITTEN_HORN_F
        else note_.pitch_midi
    )


def _make_rest(atom: ScoreAtom, beat_ql: Fraction) -> note.Rest:
    """Rest element for one committed rest atom.

    A ``whole`` rest atom that fills a measure whose written length differs
    from a whole note (6/8, 2/4, clipped measures) is the *measure-rest
    convention*: music21 emits ``<rest measure="yes"/>`` for a rest that
    fills its measure, so it is built from the exact quarterLength rather
    than the ``whole`` type.
    """
    try:
        d = _typed_duration(atom, beat_ql)
    except NotationError:
        if atom.symbol != "whole" or atom.tuplet is not None:
            raise
        return note.Rest(quarterLength=atom.duration_beats * beat_ql)
    rest = note.Rest()
    rest.duration = d
    return rest


def _render_entries(
    measure: stream.Measure,
    span: MeasureSpan,
    entries: list[_Entry],
    beat_ql: Fraction,
    strict: bool,
    presentation: PitchSpace,
) -> None:
    """Insert a measure's elements (committed atoms or legacy fragments).

    ``strict`` mode (the part carries canonical rests) requires the entries
    to tile the measure exactly — every atom the quantizer committed is
    rendered, nothing is invented.  Legacy mode fills gaps with
    ``quarterLength`` rests as before.
    """
    entries.sort(key=lambda e: e.local_start_beats)

    if strict:
        cursor = Fraction(0)
        for e in entries:
            if e.local_start_beats != cursor:
                raise NotationError(
                    f"canonical rests do not tile measure {span.number}: "
                    f"gap/overlap at beat {cursor} (next element at "
                    f"{e.local_start_beats})"
                )
            cursor = e.local_end_beats
        if cursor != span.duration_beats:
            raise NotationError(
                f"canonical rests do not tile measure {span.number}: "
                f"elements end at {cursor}, measure ends at "
                f"{span.duration_beats}"
            )

    placed: list[tuple[_Entry, note.GeneralNote]] = []
    cursor = Fraction(0)
    for e in entries:
        if not strict and e.local_start_beats > cursor:
            gap = note.Rest(quarterLength=(e.local_start_beats - cursor) * beat_ql)
            measure.insert(cursor * beat_ql, gap)
        if e.kind == "rest":
            assert e.atom is not None
            element: note.GeneralNote = _make_rest(e.atom, beat_ql)
        else:
            assert e.note_ is not None
            m21_note = note.Note()
            if e.atom is not None:
                m21_note.duration = _typed_duration(e.atom, beat_ql)
            else:
                m21_note.duration = duration.Duration(
                    quarterLength=e.dur_beats * beat_ql
                )
            m21_note.pitch = pitch.Pitch(midi=_pitch_midi(e.note_, presentation))
            m21_note.id = musicxml_note_id(e.note_.id)
            if e.atom is not None:
                is_last = e.atom_index == len(e.note_.atoms) - 1
                n_tie = _atom_tie(e.atom, e.atom_index == 0, is_last, e.note_)
            else:
                n_tie = _tie_for(e.piece_index, e.piece_count, e.note_)
            if n_tie is not None:
                m21_note.tie = n_tie
            element = m21_note
        measure.insert(e.local_start_beats * beat_ql, element)
        placed.append((e, element))
        cursor = e.local_end_beats

    if not strict and cursor < span.duration_beats:
        measure.insert(
            cursor * beat_ql,
            note.Rest(quarterLength=(span.duration_beats - cursor) * beat_ql),
        )

    _mark_tuplet_groups(placed)


def _mark_tuplet_groups(placed: list[tuple[_Entry, note.GeneralNote]]) -> None:
    """Set ``<tuplet>`` start/stop types on each committed tuplet group.

    Groups are delimited by ``atom.tuplet_group_start`` (committed by the
    quantizer bridge) and never span measures or note/rest boundaries, so
    one pass over this measure's elements suffices.
    """
    open_group: list[note.GeneralNote] = []

    def close() -> None:
        if not open_group:
            return
        if len(open_group) == 1:
            _set_tuplet_type(open_group[0], "startStop")
        else:
            _set_tuplet_type(open_group[-1], "stop")
        open_group.clear()

    for entry, element in placed:
        atom = entry.atom
        if atom is not None and atom.tuplet is not None:
            if atom.tuplet_group_start or not open_group:
                close()
                _set_tuplet_type(element, "start")
            open_group.append(element)
        else:
            close()
    close()


def _set_tuplet_type(
    element: note.GeneralNote, type_: Literal["start", "stop", "startStop"]
) -> None:
    tuplets = element.duration.tuplets
    if not tuplets:
        raise NotationError("tuplet group marker on an element without a tuplet")
    tuplets[0].type = type_


def _build_part_measures(
    payload: ScoreRevisionPayload,
    part_notes: list[QuantizedNote],
    part_rests: tuple[ScoreRest, ...],
    part_name: str,
    spans: tuple[MeasureSpan, ...],
    presentation: PitchSpace,
) -> stream.Part:
    beat_ql = beat_ql_of(payload)
    strict = bool(part_rests)
    part = stream.Part()
    part.partName = part_name
    if presentation is PitchSpace.WRITTEN_HORN_F:
        part.insert(0, instrument.Horn())

    tempo_marks: dict[int, list[tuple[Fraction, tempo.MetronomeMark]]] = {}
    for seg in payload.tempo_map:
        mark = tempo.MetronomeMark(number=seg.bpm)
        for idx, span in enumerate(spans):
            if span.start_beat <= seg.start_beat < span.end_beat:
                tempo_marks.setdefault(idx, []).append((seg.start_beat - span.start_beat, mark))
                break
        else:
            # Segment begins at/after the content end: keep the tempo
            # change by anchoring it to the end of the final measure.
            tempo_marks.setdefault(len(spans) - 1, []).append(
                (spans[-1].duration_beats, mark)
            )

    # #133 key map: each KeyChange becomes a KeySignature at its offset
    # inside the containing measure (mid-measure modulations land on the
    # beat they start at). With no key_changes the head signature is
    # emitted on the first measure as before.
    key_marks: dict[int, list[tuple[Fraction, key.KeySignature]]] = {}
    if payload.key_changes:
        for change in payload.key_changes:
            ks = change.key_signature
            if presentation is PitchSpace.WRITTEN_HORN_F:
                ks = horn_f.written_key_signature(ks)
            ks_mark = key.KeySignature(ks.fifths)
            for idx, span in enumerate(spans):
                if span.start_beat <= change.start_beat < span.end_beat:
                    key_marks.setdefault(idx, []).append(
                        (change.start_beat - span.start_beat, ks_mark)
                    )
                    break
            else:
                key_marks.setdefault(len(spans) - 1, []).append(
                    (spans[-1].duration_beats, ks_mark)
                )

    entries_by_measure = _measure_entries(part_notes, part_rests, spans)

    for idx, span in enumerate(spans):
        measure = stream.Measure(number=span.number)
        if span.implicit:
            # music21 maps MusicXML implicit="yes" to showNumber=NEVER.
            measure.showNumber = stream_enums.ShowNumber.NEVER

        if idx == 0 and not key_marks.get(0):
            ks = payload.key_signature
            if presentation is PitchSpace.WRITTEN_HORN_F:
                ks = horn_f.written_key_signature(ks)
            measure.insert(0, key.KeySignature(ks.fifths))
        if idx == 0:
            ts = span.time_signature
            measure.insert(0, meter.TimeSignature(f"{ts.beats_per_measure}/{ts.beat_unit}"))
            measure.insert(0, clef.TrebleClef())
        elif span.meter_change:
            ts = span.time_signature
            measure.insert(
                0, meter.TimeSignature(f"{ts.beats_per_measure}/{ts.beat_unit}")
            )

        for local_beat, ks_mark in key_marks.get(idx, []):
            measure.insert(local_beat * beat_ql, ks_mark)

        for local_beat, mark in tempo_marks.get(idx, []):
            measure.insert(local_beat * beat_ql, mark)

        _render_entries(
            measure,
            span,
            entries_by_measure.get(idx, []),
            beat_ql,
            strict,
            presentation,
        )

        # Declared partial measures (anacrusis, meter-change clips, a short
        # final bar) must not be silently padded by music21 with hidden
        # rests — the deficit is metrical, not content.  paddingLeft covers
        # the portion of the measure cycle before the span (pickup/phased
        # segment starts), paddingRight the portion after it.
        measure_len_ql = measure_length_beats(span.time_signature, beat_ql) * beat_ql
        pad_left = span.cycle_offset_beats * beat_ql
        pad_right = measure_len_ql - pad_left - span.duration_beats * beat_ql
        if pad_left > 0:
            measure.paddingLeft = pad_left
        if pad_right > 0:
            measure.paddingRight = pad_right

        part.append(measure)
    return part


def build_music21_score(
    score: ScoreDocument,
    presentation: PitchSpace = PitchSpace.CONCERT,
) -> stream.Score:
    """Render *score* (canonical concert pitch) into a music21 ``Score``.

    ``presentation`` selects the export presentation: ``CONCERT`` renders
    sounding pitches verbatim; ``WRITTEN_HORN_F`` renders every part
    projected +P5 with the written key signature and Horn in F
    ``<transpose>`` metadata.
    """
    if score.pitch_space is not PitchSpace.CONCERT:
        raise NotationError("canonical ScoreDocument must be concert pitch")
    payload = score.payload
    spans = measure_spans(payload)

    m21_score = stream.Score()
    if score.title:
        m21_score.insert(0, metadata.Metadata(title=score.title))

    for part in payload.parts:
        ordered = sorted(part.notes, key=lambda n: (n.start_beat, n.id))
        _check_monophonic(tuple(ordered))
        m21_score.append(
            _build_part_measures(
                payload, list(ordered), part.rests, part.name, spans, presentation
            )
        )
    return m21_score

"""Score-level rhythm edits on the canonical payload (#115, spec 13).

The simple note edits (pitch shift, delete/restore, enharmonic respell)
are MusicXML-level rewrites the desktop applies client-side. The three
remaining §13 edits change *timing*, so they must re-realize notation:

* ``setDuration`` — a new written duration for one canonical note;
* ``shiftOnset`` — move a note by whole minimum-grid steps;
* ``toggleTie`` — tie/untie a note to the contiguous next same-pitch
  note (a flag pair on the canonical notes; atoms are untouched).

Timing edits rebuild the smallest measure-aligned window containing
the note's old and new spans: notes inside are re-decomposed through
the same :class:`SpanRealizer` the quantizer used, gaps become rests,
and the monophonic contract is re-applied (a note may never cross the
next onset — an edit that would is rejected, not silently clipped).
"""

from __future__ import annotations

from dataclasses import dataclass, replace
from fractions import Fraction
from typing import Any

from hornscribe.domain.events import RawNoteEvent
from hornscribe.domain.ids import (
    RawNoteEventId,
    ScoreNoteId,
    TranscriptionRevisionId,
    derive_transcription_revision_id,
)
from hornscribe.domain.score import (
    MeasureSpan,
    Part,
    QuantizedNote,
    ScoreAtom,
    ScoreDocument,
    ScoreRest,
    ScoreRevisionPayload,
    TempoSegment,
    TimeSignature,
    beat_ql_of,
    measure_spans,
)
from hornscribe.rhythm.contracts import NormalizedNote, RhythmAtom
from hornscribe.rhythm.meter import MeterMap, MeterSegment
from hornscribe.rhythm.profile import QuantizationProfile
from hornscribe.rhythm.quantizer import quantize_events
from hornscribe.rhythm.realize import SpanRealizer
from hornscribe.rhythm.timewarp import TimeWarp
from hornscribe.rhythm.triplet import (
    TripletRegion,
    enabled_triplet_regions,
    region_evidence,
)

from .options import _PROFILES, _TRIPLET_POLICIES
from .scorebuild import _part_content


class ScoreEditError(ValueError):
    """An edit that cannot be applied honestly (mapped to INVALID_PARAMS)."""


@dataclass(frozen=True)
class ScoreEdit:
    """One rhythm edit against the canonical payload.

    ``kind``: ``"setDuration"`` | ``"shiftOnset"`` | ``"toggleTie"``.
    ``noteId``: canonical ``sn-*`` id. ``durationBeats`` is the new
    written length for setDuration; ``steps`` is the signed grid-step
    count for shiftOnset (one step = min_note_value_ql).
    """

    kind: str
    note_id: ScoreNoteId
    duration_beats: Fraction | None = None
    steps: int = 0
    bpm: float | None = None
    beats_per_measure: int | None = None
    beat_unit: int | None = None
    settings: dict[str, Any] | None = None

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreEdit:
        kind = data.get("kind")
        if kind not in (
            "setDuration",
            "shiftOnset",
            "toggleTie",
            "setTempo",
            "setMeter",
            "requantize",
            "splitNote",
            "mergeNotes",
        ):
            raise ScoreEditError(
                "edit.kind must be setDuration/shiftOnset/toggleTie/"
                f"setTempo/setMeter/requantize/splitNote/mergeNotes, "
                f"got {kind!r}"
            )
        note_id = data.get("noteId")
        if kind in ("setTempo", "setMeter", "requantize"):
            note_id = note_id if isinstance(note_id, str) else ""
        elif not isinstance(note_id, str) or not note_id:
            raise ScoreEditError("edit.noteId must be a non-empty string")
        bpm_raw = data.get("bpm")
        bpm: float | None = None
        if bpm_raw is not None:
            if isinstance(bpm_raw, bool) or not isinstance(
                bpm_raw, (int, float)
            ):
                raise ScoreEditError(
                    f"edit.bpm must be a number, got {bpm_raw!r}"
                )
            bpm = float(bpm_raw)
            if not (20.0 <= bpm <= 400.0):
                raise ScoreEditError(
                    f"edit.bpm {bpm} outside the supported 20–400 range"
                )
        if kind == "setTempo" and bpm is None:
            raise ScoreEditError("setTempo requires bpm")
        beats_per_measure = _opt_int(data, "beatsPerMeasure")
        beat_unit = _opt_int(data, "beatUnit")
        if kind == "setMeter":
            if beats_per_measure is None or beat_unit is None:
                raise ScoreEditError(
                    "setMeter requires beatsPerMeasure and beatUnit"
                )
            if not (1 <= beats_per_measure <= 64):
                raise ScoreEditError(
                    f"beatsPerMeasure {beats_per_measure} outside 1-64"
                )
            if beat_unit not in (1, 2, 4, 8, 16, 32, 64):
                raise ScoreEditError(
                    f"beatUnit {beat_unit} must be a power of two (1-64)"
                )
        settings = _requantize_settings(data, kind)
        duration = data.get("durationBeats")
        try:
            duration_beats = (
                Fraction(duration) if duration is not None else None
            )
            if isinstance(duration, bool):
                raise ValueError("bool")
        except (TypeError, ValueError, ZeroDivisionError) as exc:
            raise ScoreEditError(
                f"edit.durationBeats is not a rational number: {duration!r}"
            ) from exc
        steps = data.get("steps", 0)
        if not isinstance(steps, int) or isinstance(steps, bool):
            raise ScoreEditError(f"edit.steps must be an int, got {steps!r}")
        return cls(
            kind=kind,
            note_id=ScoreNoteId(note_id),
            duration_beats=duration_beats,
            steps=steps,
            bpm=bpm,
            beats_per_measure=beats_per_measure,
            beat_unit=beat_unit,
            settings=settings,
        )


def _opt_int(data: dict[str, Any], key: str) -> int | None:
    raw = data.get(key)
    if raw is None:
        return None
    if isinstance(raw, bool) or not isinstance(raw, int):
        raise ScoreEditError(f"edit.{key} must be an int, got {raw!r}")
    return raw


_REQUANTIZE_KEYS = {"minDurationQl", "triplets", "simplicity"}


def _requantize_settings(
    data: dict[str, Any], kind: str
) -> dict[str, Any] | None:
    """Validate the requantize settings overrides (#130).

    Only the quantization profile knobs are accepted — tempo and meter
    have their own edits, and unknown keys are rejected rather than
    silently ignored so a typo never looks like it applied.
    """
    raw = data.get("settings")
    if raw is None:
        if kind == "requantize":
            raise ScoreEditError("requantize requires a settings object")
        return None
    if not isinstance(raw, dict):
        raise ScoreEditError("edit.settings must be an object")
    unknown = set(raw) - _REQUANTIZE_KEYS
    if unknown:
        raise ScoreEditError(
            f"unknown requantize settings: {sorted(unknown)}"
        )
    out: dict[str, Any] = {}
    if "minDurationQl" in raw:
        try:
            value = Fraction(raw["minDurationQl"])
        except (TypeError, ValueError, ZeroDivisionError) as exc:
            raise ScoreEditError(
                "settings.minDurationQl is not a rational number: "
                f"{raw['minDurationQl']!r}"
            ) from exc
        if value <= 0:
            raise ScoreEditError("settings.minDurationQl must be > 0")
        out["minDurationQl"] = str(value)
    if "triplets" in raw:
        value = raw["triplets"]
        if value not in _TRIPLET_POLICIES:
            raise ScoreEditError(
                f"settings.triplets must be one of "
                f"{sorted(_TRIPLET_POLICIES)}, got {value!r}"
            )
        out["triplets"] = value
    if "simplicity" in raw:
        value = raw["simplicity"]
        if value not in _PROFILES:
            raise ScoreEditError(
                f"settings.simplicity must be one of "
                f"{sorted(_PROFILES)}, got {value!r}"
            )
        out["simplicity"] = value
    if kind == "requantize" and not out:
        raise ScoreEditError("requantize needs at least one setting")
    return out or None


def _profile_from_settings(settings: dict[str, Any]) -> QuantizationProfile:
    """Rebuild the quantization profile the payload was produced with."""
    kind = settings.get("simplicity", "standard")
    factory = _PROFILES.get(kind, QuantizationProfile.standard)
    base = factory()
    min_dur = settings.get("minDurationQl", "1/4")
    triplets = settings.get("triplets", "auto")
    return replace(
        base,
        min_note_value_ql=Fraction(min_dur),
        triplet_policy=_TRIPLET_POLICIES.get(triplets, base.triplet_policy),
    )


def _meter_map_from_payload(payload: ScoreRevisionPayload) -> MeterMap:
    """Rebuild the meter map the payload's measure layout derives from."""
    beat_ql = beat_ql_of(payload)
    if payload.meter_changes:
        segments = tuple(
            MeterSegment(
                start_ql=c.start_beat * beat_ql,
                numerator=c.time_signature.beats_per_measure,
                denominator=c.time_signature.beat_unit,
                measure_phase_ql=c.measure_phase_beats * beat_ql,
            )
            for c in payload.meter_changes
        )
        return MeterMap(segments)
    ts = payload.time_signature
    measure_len = Fraction(ts.beats_per_measure * 4, ts.beat_unit)
    pickup_ql = payload.pickup_beats * beat_ql
    phase = (measure_len - pickup_ql) % measure_len if pickup_ql else Fraction(0)
    return MeterMap(
        (
            MeterSegment(
                start_ql=Fraction(0),
                numerator=ts.beats_per_measure,
                denominator=ts.beat_unit,
                measure_phase_ql=phase,
            ),
        )
    )


def _triplet_regions(
    notes: tuple[QuantizedNote, ...],
    meter_map: MeterMap,
    profile: QuantizationProfile,
    beat_ql: Fraction,
) -> tuple[TripletRegion, ...]:
    """Recompute the evidence-gated triplet regions for the edited notes."""
    normalized = tuple(
        NormalizedNote(
            source_id=n.source_event_ids[0]
            if n.source_event_ids
            else RawNoteEventId(str(n.id)),
            pitch_midi=n.pitch_midi,
            onset_ql=float(n.start_beat * beat_ql),
            offset_ql=float(n.end_beat * beat_ql),
        )
        for n in notes
    )
    if not normalized:
        return ()
    return enabled_triplet_regions(
        region_evidence(normalized, meter_map, profile), profile
    )


def _find_note(part: Part, note_id: ScoreNoteId) -> int:
    for i, n in enumerate(part.notes):
        if n.id == note_id:
            return i
    raise ScoreEditError(f"note {note_id} not found in the score")


def _clip_overlaps(
    notes: list[QuantizedNote], *, edited_index: int
) -> list[QuantizedNote]:
    """Re-apply the monophonic contract inside the edit window.

    An earlier note may never cross the next onset — it clips. The
    *edited* note is the exception: crossing the next onset is a user
    error (the requested span simply does not fit), so it raises rather
    than silently shortening the user's request.
    """
    out: list[QuantizedNote] = []
    for note in notes:
        if out:
            prev = out[-1]
            if prev.end_beat > note.start_beat:
                if len(out) - 1 == edited_index:
                    # The edited note may never be clipped — the user
                    # asked for a span that does not fit; say so instead
                    # of silently shortening their request.
                    raise ScoreEditError(
                        "the requested span extends past the next "
                        "note's onset"
                    )
                clipped = note.start_beat - prev.start_beat
                if clipped <= 0:
                    raise ScoreEditError(
                        f"note {prev.id} would vanish under the edit"
                    )
                out[-1] = replace(prev, duration_beats=clipped)
        out.append(note)
    # Forward check for the edited note: its end may not cross the next
    # onset (the user asked for a span that does not fit).
    idx = edited_index
    if idx + 1 < len(out) and out[idx].end_beat > out[idx + 1].start_beat:
        raise ScoreEditError(
            "the requested span extends past the next note's onset"
        )
    return out


def _tuplet_group_starts(atoms: list[RhythmAtom]) -> list[bool]:
    """Mark the first atom of each consecutive tuplet run (scorebuild)."""
    flags: list[bool] = []
    in_group = False
    for atom in atoms:
        if atom.tuplet is not None and not in_group:
            flags.append(True)
            in_group = True
        else:
            flags.append(False)
            in_group = atom.tuplet is not None
    return flags


def _atom_to_score(
    atom: RhythmAtom, beat_ql: Fraction, group_start: bool
) -> ScoreAtom:
    return ScoreAtom(
        duration_beats=atom.duration_ql / beat_ql,
        symbol=atom.symbol,
        dots=atom.dots,
        tuplet=atom.tuplet,
        tuplet_group_start=group_start,
        tie_to_next=atom.tie_to_next,
    )


def _retile_window(
    window_notes: list[QuantizedNote],
    lo: Fraction,
    hi: Fraction,
    realizer: SpanRealizer,
    beat_ql: Fraction,
) -> tuple[list[QuantizedNote], list[ScoreRest]]:
    """Re-decompose notes + rest gaps inside the edit window.

    The merged atom stream (notes + rests in onset order) gets tuplet
    group flags across the window — mirrors build_score's flow so a
    group still brackets correctly. Window bounds are measure edges,
    so tie/atom structure never crosses the splice.
    """
    events: list[tuple[Fraction, str, int]] = [
        (n.start_beat, "note", i) for i, n in enumerate(window_notes)
    ]
    gaps: list[tuple[Fraction, Fraction]] = []
    # Gaps tile the whole window — including the edges, where the
    # measure's content may not reach the barline (a shortened note
    # leaves a rest behind it).
    cursor = lo
    for n in sorted(window_notes, key=lambda n: n.start_beat):
        if n.start_beat > cursor:
            gaps.append((cursor, n.start_beat))
        cursor = max(cursor, n.end_beat)
    if cursor < hi:
        gaps.append((cursor, hi))
    events += [(g[0], "rest", i) for i, g in enumerate(gaps)]
    events.sort(key=lambda e: e[0])

    stream: list[RhythmAtom] = []
    note_ranges: list[tuple[int, int]] = [(0, 0)] * len(window_notes)
    rest_ranges: list[tuple[int, int]] = [(0, 0)] * len(gaps)
    for _pos, kind, i in events:
        if kind == "note":
            n = window_notes[i]
            notation = realizer.realize_span(
                n.start_beat * beat_ql, n.end_beat * beat_ql, is_rest=False
            ).notation
            atoms = notation.atoms if notation is not None else ()
            start = len(stream)
            stream.extend(atoms)
            note_ranges[i] = (start, len(stream))
        else:
            s, e = gaps[i]
            rest_notation = realizer.rest_span(s * beat_ql, e * beat_ql)
            atoms = rest_notation.atoms if rest_notation is not None else ()
            start = len(stream)
            stream.extend(atoms)
            rest_ranges[i] = (start, len(stream))
    flags = _tuplet_group_starts(stream)

    new_notes = [
        replace(
            n,
            atoms=tuple(
                _atom_to_score(a, beat_ql, flags[lo + j])
                for j, a in enumerate(stream[lo:hi])
            ),
        )
        for n, (lo, hi) in zip(window_notes, note_ranges, strict=True)
    ]
    new_rests = [
        ScoreRest(
            start_beat=gaps[i][0],
            atoms=tuple(
                _atom_to_score(a, beat_ql, flags[lo + j])
                for j, a in enumerate(stream[lo:hi])
            ),
        )
        for i, (lo, hi) in enumerate(rest_ranges)
        if lo < hi
    ]
    return (new_notes, new_rests)


def _expand_window(
    notes: tuple[QuantizedNote, ...],
    spans: tuple[MeasureSpan, ...],
    lo: Fraction,
    hi: Fraction,
) -> tuple[Fraction, Fraction]:
    """Grow ``[lo, hi)`` to whole measures covering every intersecting note."""
    for n in notes:
        if n.start_beat < hi and n.end_beat > lo:
            lo = min(lo, n.start_beat)
            hi = max(hi, n.end_beat)
    for span in spans:
        if span.start_beat < hi and span.end_beat > lo:
            lo = min(lo, span.start_beat)
            hi = max(hi, span.end_beat)
    return (lo, hi)


def _retile_part(
    payload: ScoreRevisionPayload,
    part: Part,
    notes: list[QuantizedNote],
    lo: Fraction,
    hi: Fraction,
) -> Part:
    """Re-decompose the notes intersecting [lo, hi) and splice back.

    Shared tail of every structural edit (timing, split, merge): the
    window grows to whole measures covering straddling notes, the
    realizer rebuilds atoms + rest gaps inside it, and content outside
    the window is kept verbatim.
    """
    beat_ql = beat_ql_of(payload)
    spans = measure_spans(payload)
    prev = None
    while (lo, hi) != prev:
        prev = (lo, hi)
        lo, hi = _expand_window(tuple(notes), spans, lo, hi)
    window_notes = [
        n for n in notes if n.start_beat < hi and n.end_beat > lo
    ]

    profile = _profile_from_settings(payload.quantization_settings)
    meter_map = _meter_map_from_payload(payload)
    regions = _triplet_regions(tuple(notes), meter_map, profile, beat_ql)
    realizer = SpanRealizer(meter_map, profile, triplet_regions=regions)
    try:
        new_window, new_rests = _retile_window(
            window_notes, lo, hi, realizer, beat_ql
        )
    except ValueError as exc:
        raise ScoreEditError(
            f"the edited rhythm cannot be written in this meter: {exc}"
        ) from exc
    window_ids = {n.id for n in window_notes}
    final_notes = tuple(
        n if n.id not in window_ids else next(
            w for w in new_window if w.id == n.id
        )
        for n in notes
    )
    kept_rests = [
        r for r in part.rests if r.end_beat <= lo or r.start_beat >= hi
    ]
    return replace(
        part,
        notes=final_notes,
        rests=tuple(sorted(kept_rests + new_rests, key=lambda r: r.start_beat)),
    )


def _apply_timing_edit(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
    new_start: Fraction | None,
    new_duration: Fraction | None,
) -> Part:
    """Rebuild the part after a timing edit (setDuration/shiftOnset)."""
    part = payload.parts[part_index]
    notes = list(part.notes)
    target = notes[note_index]
    start = new_start if new_start is not None else target.start_beat
    duration = (
        new_duration if new_duration is not None else target.duration_beats
    )
    if duration <= 0:
        raise ScoreEditError("duration must be positive")
    if start < 0:
        raise ScoreEditError("the note cannot start before the score")
    notes[note_index] = replace(
        target, start_beat=start, duration_beats=duration
    )
    notes.sort(key=lambda n: (n.start_beat, n.id))
    edited_index = next(i for i, n in enumerate(notes) if n.id == target.id)
    notes = _clip_overlaps(notes, edited_index=edited_index)

    # The rebuild window: every measure touching the union of old and
    # new spans, grown to cover notes straddling its edges.
    lo = min(target.start_beat, start)
    hi = max(target.end_beat, start + duration)
    return _retile_part(payload, part, notes, lo, hi)


def _apply_split(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
) -> Part:
    """Split a note at its midpoint (§13 post-MVP split).

    The midpoint is snapped to the minimum grid so both halves stay
    writable; an odd-grid note (e.g. a triplet span) splits at the
    nearest grid point instead. Ties redistribute: the first half keeps
    an incoming tie, the second keeps an outgoing one, and the halves
    are never tied to each other (a split is a visible separation).
    The second half gets a fresh sn-* id continuing the document's
    numbering.
    """
    part = payload.parts[part_index]
    notes = list(part.notes)
    target = notes[note_index]
    profile = _profile_from_settings(payload.quantization_settings)
    grid = profile.min_note_value_ql
    beat_ql = beat_ql_of(payload)
    mid_ql = target.start_beat * beat_ql + target.duration_beats * beat_ql / 2
    # Snap the split point to the grid (round-half-up on the step count).
    steps = (mid_ql + grid / 2) // grid
    split_ql = steps * grid
    if not (target.start_beat * beat_ql < split_ql < target.end_beat * beat_ql):
        raise ScoreEditError(
            "the note is too short to split on the current grid"
        )
    split_beat = split_ql / beat_ql
    fresh = _next_score_note_id(payload)
    first = replace(
        target,
        duration_beats=split_beat - target.start_beat,
        tie_start=False,
        atoms=(),
    )
    second = replace(
        target,
        id=fresh,
        start_beat=split_beat,
        duration_beats=target.end_beat - split_beat,
        tie_stop=False,
        atoms=(),
    )
    notes[note_index : note_index + 1] = [first, second]
    return _retile_part(
        payload, part, notes, target.start_beat, target.end_beat
    )


def _next_score_note_id(payload: ScoreRevisionPayload) -> ScoreNoteId:
    """Fresh sn-* id continuing the document's numbering."""
    next_id = 0
    for part in payload.parts:
        for n in part.notes:
            try:
                next_id = max(next_id, int(str(n.id)[3:]) + 1)
            except ValueError:
                continue
    return ScoreNoteId(f"sn-{next_id:06d}")


def _apply_merge(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
) -> Part:
    """Merge a note with the contiguous next same-pitch note (§13 merge).

    Unlike tie-untie (which keeps two written notes), merge collapses
    the pair into ONE canonical note — the first note's id survives,
    its source_event_ids union, the second note's id is freed. The
    merged span re-tiles, so a pair split by a barline becomes a single
    tied decomposition again.
    """
    part = payload.parts[part_index]
    notes = list(part.notes)
    if note_index + 1 >= len(notes):
        raise ScoreEditError("there is no next note to merge with")
    cur = notes[note_index]
    nxt = notes[note_index + 1]
    if cur.pitch_midi != nxt.pitch_midi:
        raise ScoreEditError("a merge needs the same pitch on both notes")
    if cur.end_beat != nxt.start_beat:
        raise ScoreEditError(
            "a merge needs contiguous notes (the next note must start "
            "where this one ends)"
        )
    merged = replace(
        cur,
        duration_beats=nxt.end_beat - cur.start_beat,
        source_event_ids=cur.source_event_ids + nxt.source_event_ids,
        tie_start=nxt.tie_start,
        atoms=(),
    )
    notes[note_index : note_index + 2] = [merged]
    return _retile_part(payload, part, notes, cur.start_beat, nxt.end_beat)


def _apply_tie_toggle(
    payload: ScoreRevisionPayload,
    part_index: int,
    note_index: int,
) -> Part:
    """Flip the tie between a note and the contiguous next same-pitch note."""
    part = payload.parts[part_index]
    notes = list(part.notes)
    if note_index + 1 >= len(notes):
        raise ScoreEditError("there is no next note to tie to")
    cur = notes[note_index]
    nxt = notes[note_index + 1]
    tied = cur.tie_start and nxt.tie_stop
    if tied:
        notes[note_index] = replace(cur, tie_start=False)
        notes[note_index + 1] = replace(nxt, tie_stop=False)
        return replace(part, notes=tuple(notes))
    if cur.pitch_midi != nxt.pitch_midi:
        raise ScoreEditError("a tie needs the same pitch on both notes")
    if cur.end_beat != nxt.start_beat:
        raise ScoreEditError(
            "a tie needs contiguous notes (the next note must start "
            "where this one ends)"
        )
    notes[note_index] = replace(cur, tie_start=True)
    notes[note_index + 1] = replace(nxt, tie_stop=True)
    return replace(part, notes=tuple(notes))


def _apply_set_meter(
    payload: ScoreRevisionPayload, ts: TimeSignature
) -> ScoreRevisionPayload:
    """Set the piece's meter (§14 meter edit) and re-tile every part.

    The canonical beat axis is defined by the *first* time signature's
    beat unit (beat_ql_of), so changing the unit rescales every beat
    position by new_unit / old_unit — absolute durations are preserved.
    Notes, rest spans (re-tiled anyway), the tempo map and the pickup
    all scale together; note atoms are cleared first because a scaled
    duration would violate the atoms-tile-duration invariant.

    Mid-piece meter changes are collapsed: the edit sets the whole
    piece's meter, so the resulting payload carries none (the single
    time_signature field is authoritative again). The pickup keeps its
    absolute span — a one-beat pickup stays one notated beat under the
    new signature.
    """
    old_ts = payload.time_signature
    old_beat_ql = Fraction(4, old_ts.beat_unit)
    new_beat_ql = Fraction(4, ts.beat_unit)
    # beat_ql is the quarter-length OF one beat; positions scale by the
    # inverse so beats * beat_ql (absolute QL) is preserved.
    scale = old_beat_ql / new_beat_ql  # = ts.beat_unit / old_ts.beat_unit

    profile = _profile_from_settings(payload.quantization_settings)
    pickup_ql = payload.pickup_beats * old_beat_ql
    measure_ql = Fraction(ts.beats_per_measure) * new_beat_ql
    phase_ql = (measure_ql - pickup_ql) % measure_ql if pickup_ql else Fraction(0)
    meter_map = MeterMap(
        (
            MeterSegment(
                start_ql=Fraction(0),
                numerator=ts.beats_per_measure,
                denominator=ts.beat_unit,
                measure_phase_ql=phase_ql,
            ),
        )
    )

    new_parts: list[Part] = []
    for part in payload.parts:
        scaled: list[QuantizedNote] = []
        for n in part.notes:
            if scale == 1:
                scaled.append(n)
            else:
                scaled.append(
                    replace(
                        n,
                        start_beat=n.start_beat * scale,
                        duration_beats=n.duration_beats * scale,
                        # A scaled span invalidates the committed atom
                        # decomposition — re-tiling rebuilds it below.
                        atoms=(),
                    )
                )
        # The re-tile window covers notes AND existing rest spans so a
        # trailing rest keeps its span under the new layout.
        lo = Fraction(0)
        hi = Fraction(0)
        for n in scaled:
            hi = max(hi, n.end_beat)
        for r in part.rests:
            hi = max(hi, (r.start_beat + r.duration_beats) * scale)
        regions = _triplet_regions(tuple(scaled), meter_map, profile, new_beat_ql)
        realizer = SpanRealizer(meter_map, profile, triplet_regions=regions)
        if hi > lo:
            try:
                new_notes, new_rests = _retile_window(
                    scaled, lo, hi, realizer, new_beat_ql
                )
            except ValueError as exc:
                raise ScoreEditError(
                    "the score's rhythm cannot be written in "
                    f"{ts.beats_per_measure}/{ts.beat_unit}: {exc}"
                ) from exc
            new_parts.append(
                replace(
                    part,
                    notes=tuple(new_notes),
                    rests=tuple(new_rests),
                )
            )
        else:
            new_parts.append(replace(part, notes=tuple(scaled), rests=()))

    tempo_map = tuple(
        replace(seg, start_beat=seg.start_beat * scale)
        for seg in payload.tempo_map
    )
    # The key map rides the same beat axis: rescale change positions so
    # modulations stay glued to their measure under the new beat unit.
    key_changes = tuple(
        replace(c, start_beat=c.start_beat * scale)
        for c in payload.key_changes
    )
    return replace(
        payload,
        time_signature=ts,
        pickup_beats=pickup_ql / new_beat_ql,
        meter_changes=(),
        tempo_map=tempo_map,
        key_changes=key_changes,
        parts=tuple(new_parts),
    )


def _apply_requantize(
    payload: ScoreRevisionPayload, overrides: dict[str, Any]
) -> ScoreRevisionPayload:
    """Re-quantize every part under changed quantization settings (#130).

    The canonical notes are replayed through quantize_events as synthetic
    raw events: onset/offset seconds are the note's absolute QL span and
    the warp is the identity (fixed 60 bpm), so the DP re-searches the
    grid under the merged profile — a coarser min-duration merges
    ornament notes, a finer one splits them, and triplet policy changes
    re-decide the tuplet regions.

    Canonical ids are preserved positionally: old and new note lists are
    each in score order, and index i of the new list inherits old note
    i's id (and its source_event_ids, so review evidence still resolves).
    Extra new notes get fresh ids continuing the document's numbering;
    extra old ids disappear with their notes — review issues pointing at
    a vanished id are dropped by the caller's issue filtering.
    """
    settings = {**payload.quantization_settings, **overrides}
    profile = _profile_from_settings(settings)
    meter_map = _meter_map_from_payload(payload)
    beat_ql = beat_ql_of(payload)
    warp = TimeWarp.fixed_bpm(60.0)  # identity: seconds == quarterLength
    tr_rev = TranscriptionRevisionId(
        str(
            derive_transcription_revision_id(
                {"requantize": settings, "of": str(payload.revision_id())}
            )
        )
    )

    # Highest existing sn-* index across every part — fresh ids continue
    # from here so they never collide with a surviving note.
    next_id = 0
    for part in payload.parts:
        for n in part.notes:
            try:
                next_id = max(next_id, int(str(n.id)[3:]) + 1)
            except ValueError:
                continue

    new_parts: list[Part] = []
    for part in payload.parts:
        if not part.notes:
            new_parts.append(part)
            continue
        events: list[RawNoteEvent] = []
        event_by_id: dict[RawNoteEventId, RawNoteEvent] = {}
        for i, n in enumerate(part.notes):
            event = RawNoteEvent(
                id=RawNoteEventId(f"rne-9{i:05d}"),
                transcription_revision=tr_rev,
                pitch_midi=float(n.pitch_midi),
                onset_sec=float(n.start_beat * beat_ql),
                offset_sec=float(n.end_beat * beat_ql),
                velocity=n.velocity,
                source="requantize",
            )
            events.append(event)
            event_by_id[event.id] = event
        alternatives = quantize_events(
            events,
            warp,
            meter_map,
            profile,
            alignment_shift_sec=0.0,
        )
        if not alternatives:
            raise ScoreEditError(
                "re-quantization produced no notes for this score"
            )
        notes, rests, _conf, _onsets = _part_content(
            alternatives[0], beat_ql, event_by_id
        )
        old_sorted = sorted(
            part.notes, key=lambda n: (n.start_beat, str(n.id))
        )
        remapped: list[QuantizedNote] = []
        for i, note in enumerate(notes):
            if i < len(old_sorted):
                old = old_sorted[i]
                remapped.append(
                    replace(
                        note,
                        id=old.id,
                        source_event_ids=old.source_event_ids,
                    )
                )
            else:
                remapped.append(
                    replace(note, id=ScoreNoteId(f"sn-{next_id:06d}"))
                )
                next_id += 1
        new_parts.append(
            replace(part, notes=tuple(remapped), rests=tuple(rests))
        )

    return replace(
        payload,
        parts=tuple(new_parts),
        quantization_settings=settings,
    )


def _apply_set_tempo(
    payload: ScoreRevisionPayload, bpm: float
) -> ScoreRevisionPayload:
    """Set the piece's tempo (§14 BPM edit).

    The tempo segment at beat 0 is replaced (or prepended when the map
    starts later / is empty); later segments are kept — a mid-piece
    tempo change survives a head-tempo correction. This is a
    presentation-level edit: no re-tiling needed, so the whole payload
    is returned untouched apart from tempo_map.
    """
    segments = list(payload.tempo_map)
    if segments and segments[0].start_beat == 0:
        segments[0] = replace(segments[0], bpm=bpm)
    else:
        segments.insert(0, TempoSegment(start_beat=Fraction(0), bpm=bpm))
    return replace(payload, tempo_map=tuple(segments))


def apply_score_edit(
    document: ScoreDocument, edit: ScoreEdit
) -> ScoreDocument:
    """Apply one §13 rhythm edit and return the rebuilt document.

    The payload's canonical notes keep their ids — review issues and
    client-side note edits stay attached. A new score revision falls
    out of the changed content automatically (content-derived ids).
    """
    payload = document.payload
    beat_ql = beat_ql_of(payload)
    if edit.kind == "setTempo":
        if edit.bpm is None:
            raise ScoreEditError("setTempo requires bpm")
        new_payload = _apply_set_tempo(payload, edit.bpm)
        return replace(document, payload=new_payload)
    if edit.kind == "setMeter":
        if edit.beats_per_measure is None or edit.beat_unit is None:
            raise ScoreEditError(
                "setMeter requires beatsPerMeasure and beatUnit"
            )
        ts = TimeSignature(
            beats_per_measure=edit.beats_per_measure,
            beat_unit=edit.beat_unit,
        )
        new_payload = _apply_set_meter(payload, ts)
        return replace(document, payload=new_payload)
    if edit.kind == "requantize":
        if not edit.settings:
            raise ScoreEditError("requantize needs at least one setting")
        new_payload = _apply_requantize(payload, edit.settings)
        return replace(document, payload=new_payload)
    # Locate the note across parts (single-part today, but the loop is
    # free).
    part_index = -1
    note_index = -1
    for pi, part in enumerate(payload.parts):
        try:
            note_index = _find_note(part, edit.note_id)
            part_index = pi
            break
        except ScoreEditError:
            continue
    if part_index < 0:
        raise ScoreEditError(f"note {edit.note_id} not found in the score")
    part = payload.parts[part_index]
    target = part.notes[note_index]

    if edit.kind == "toggleTie":
        new_part = _apply_tie_toggle(payload, part_index, note_index)
    elif edit.kind == "splitNote":
        new_part = _apply_split(payload, part_index, note_index)
    elif edit.kind == "mergeNotes":
        new_part = _apply_merge(payload, part_index, note_index)
    else:
        if edit.kind == "setDuration":
            if edit.duration_beats is None:
                raise ScoreEditError("setDuration requires durationBeats")
            new_start, new_duration = None, edit.duration_beats
        else:  # shiftOnset
            if edit.steps == 0:
                raise ScoreEditError("shiftOnset requires a non-zero steps")
            profile = _profile_from_settings(payload.quantization_settings)
            step_beats = profile.min_note_value_ql / beat_ql
            new_start = target.start_beat + step_beats * edit.steps
            new_duration = None
        new_part = _apply_timing_edit(
            payload, part_index, note_index, new_start, new_duration
        )
    parts = list(payload.parts)
    parts[part_index] = new_part
    new_payload = replace(payload, parts=tuple(parts))
    return replace(document, payload=new_payload)
